'use strict';
(async()=>{
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lines=v=>String(v||'').split('\n').map(v=>v.trim()).filter(Boolean);
const active=list=>(list||[]).filter(v=>v.status==='published');
const set=(sel,value)=>{const el=$(sel);if(el)el.textContent=value||''};
const safe=(v,image=false)=>{if(typeof v!=='string'||/[\s\\\u0000-\u001f]/.test(v))return '';if(/^\/(assets|uploads)\/[\w./-]+$/.test(v)&&!v.includes('..'))return v;if(!image&&/^#[\w-]+$/.test(v))return v;try{const u=new URL(v);return u.protocol==='https:'&&!u.username&&!u.password?v:''}catch{return ''}};
const image=(url,alt,cls='')=>safe(url,true)?`<img class="${cls}" src="${esc(safe(url,true))}" alt="${esc(alt)}" loading="lazy">`:'';
const validContent=d=>d&&['home','settings','seo'].every(k=>d[k]&&typeof d[k]==='object'&&!Array.isArray(d[k])&&Object.values(d[k]).every(v=>typeof v==='string'))&&['services','founders','pricing','faq','blog','projects'].every(k=>Array.isArray(d[k])&&d[k].every(v=>v&&typeof v.id==='string'&&typeof v.status==='string'))&&d.services.every(v=>['name','deliverables','process'].every(k=>typeof v[k]==='string'))&&d.blog.every(v=>typeof v.body==='string')&&d.founders.every(v=>typeof v.phone==='string');
let data,connected=false;
if(new URLSearchParams(location.search).get('preview')==='admin'){
 try{const draft=JSON.parse(sessionStorage.getItem('cn-preview-content'));if(validContent(draft))data=draft;}catch{}
 if(data){const notice=document.createElement('div');notice.className='cms-preview-label';notice.textContent='DRAFT PREVIEW · Not published';document.body.prepend(notice)}
}else if(window.CLOUD_NEST_API_ORIGIN){
 try{const r=await fetch(window.CLOUD_NEST_API_ORIGIN+'/api/public/content',{signal:AbortSignal.timeout(5000)});if(r.ok){const content=(await r.json()).content;if(validContent(content)){data=content;connected=true;}}}catch{}
}
if(data){
 window.cloudNestData=data;
 const h=data.home;set('.hero .eyebrow','');$('.hero .eyebrow').innerHTML='<span class="small-line"></span> '+esc(h.label);
 document.querySelectorAll('.hero-line').forEach((el,i)=>el.textContent=h['line'+(i+1)]);$('.hero h1').setAttribute('aria-label',[h.line1,h.line2,h.line3].join(' '));set('.hero-content > p',h.description);
 const cta=$('.hero-actions .primary');cta.innerHTML=esc(h.buttonText)+' <span>↗</span>';cta.href=safe(h.buttonLink)||'#contact';const secondary=$('.hero-actions .text-link');secondary.innerHTML=esc(h.secondaryText)+' <span>↓</span>';secondary.href=safe(h.secondaryLink)||'#services';
 if(safe(h.image,true))$('.hero-art').style.setProperty('--hero-image',`url("${safe(h.image,true).replaceAll('"','%22')}")`);
 set('.statement-content h2',h.aboutTitle);set('.statement-content > p',h.aboutDescription);set('#services h2',h.servicesTitle);set('#services .section-heading > p',h.servicesDescription);set('.contact-heading h2',h.contactTitle);set('.contact-heading > p',h.contactDescription);
 $('.services-grid').innerHTML=active(data.services).map((r,i)=>`<a class="service-card reveal" href="#contact" aria-haspopup="dialog" aria-controls="service-dialog" data-service="${esc(r.name)}"><div class="card-top"><span class="service-symbol">${esc(r.icon)}</span><span class="card-number">${String(i+1).padStart(2,'0')}</span></div>${image(r.image,r.name,'cms-service-image')}<h3>${esc(r.name)}</h3><p>${esc(r.shortDescription)}</p><div class="card-bottom"><span>${esc(r.tags)}</span><span class="round-arrow">↗</span></div></a>`).join('');
 $('#service-select').innerHTML='<option value="Not sure yet">Select a service</option>'+active(data.services).map(r=>`<option>${esc(r.name)}</option>`).join('')+'<option>A combination of services</option>';
 $('.founder-grid').innerHTML=active(data.founders).map(r=>`<article class="founder-card cms-founder${r.image?' cms-founder-with-photo':''} reveal"><div class="cms-founder-info"><span class="founder-kicker">THE PEOPLE BEHIND CLOUD NEST</span><h3>${esc(r.name)}</h3><p>${esc(r.role)}</p><span class="founder-line"></span>${r.phone?`<a href="tel:${esc(r.phone.replace(/[^+\d]/g,''))}"><span>↗</span>${esc(r.phone)}</a>`:''}${r.email?`<a href="mailto:${esc(r.email)}"><span>✉</span>${esc(r.email)}</a>`:''}</div><div class="cms-founder-brand">${image(r.image||data.settings.logo,r.image?r.name:'Cloud Nest')}${r.image?'':'<p>Your vision.<br>Our design.</p>'}</div></article>`).join('');
 $('.pricing-grid').innerHTML=active(data.pricing).map(r=>`<article class="price-card ${r.recommended?'featured':''} reveal"><span class="plan-kicker">${esc(r.label)}</span><h3>${esc(r.name)}</h3><p>${esc(r.description)}</p><div class="price">${esc(r.price)}</div><span class="price-note">${esc(r.note)}</span><ul>${lines(r.features).map(v=>`<li>${esc(v)}</li>`).join('')}</ul><a href="#contact" data-plan="${esc(r.name)}" class="button ${r.recommended?'primary':'outline'}">Discuss ${esc(r.name)} <span>↗</span></a></article>`).join('');
 $('#plan-select').innerHTML='<option value="Let’s discuss">Let’s discuss</option>'+active(data.pricing).map(r=>`<option>${esc(r.name)}</option>`).join('');
 const faq=$('#faq details')?.parentElement;if(faq)faq.innerHTML=active(data.faq).map(r=>`<details><summary>${esc(r.question)}<span>+</span></summary><p>${esc(r.answer)}</p></details>`).join('');
 $('.journal-grid').innerHTML=active(data.blog).map((r,i)=>`<button class="journal-card reveal" data-article="${esc(r.id)}"><div class="journal-art art-${['one','two','three'][i%3]}">${r.image?image(r.image,r.title):`<span class="editorial-word">${esc(r.category||'Journal')}<br><i>${String(i+1).padStart(2,'0')}.</i></span>`}</div><div class="article-meta"><span>${esc(r.category||'Journal')}</span><span>Read article ↗</span></div><h3>${esc(r.title)}</h3></button>`).join('');
 const projects=active(data.projects);if(projects.length){const section=document.createElement('section');section.className='section-pad cms-projects';section.id='projects';section.innerHTML=`<div class="section-heading reveal"><div><div class="eyebrow">SELECTED WORK</div><h2>${esc(h.projectsTitle)}</h2></div><p>${esc(h.projectsDescription)}</p></div><div class="journal-grid">${projects.map(r=>`<button class="journal-card reveal" data-project="${esc(r.id)}">${r.image?`<div class="journal-art">${image(r.image,r.title)}</div>`:''}<div class="article-meta"><span>${esc(r.category)}</span><span>View project ↗</span></div><h3>${esc(r.title)}</h3><p>${esc(r.client)}</p></button>`).join('')}</div>`;$('#pricing').before(section);}
 set('.footer-top > p',data.settings.tagline);set('.footer-bottom > span:first-child',data.settings.copyright);
 document.querySelectorAll('.brand').forEach(el=>{const brandImg=image(data.settings.logo,'');el.innerHTML=(brandImg?'<span class="brand-icon">'+brandImg+'</span>':'')+esc(data.settings.companyName)});
 document.querySelectorAll('.contact-brand img').forEach(el=>{if(safe(data.settings.logo,true))el.src=safe(data.settings.logo,true)});
 const contacts=$('.cms-contact-details')||document.createElement('div');contacts.className='cms-contact-details';contacts.innerHTML=`${data.settings.email?`<a href="mailto:${esc(data.settings.email)}">${esc(data.settings.email)}</a>`:''}${data.settings.phone?`<a href="tel:${esc(data.settings.phone.replace(/[^+\d]/g,''))}">${esc(data.settings.phone)}</a>`:''}${data.settings.address?`<p>${esc(data.settings.address)}</p>`:''}<div>${['facebook','instagram','linkedin','youtube'].filter(k=>safe(data.settings[k])).map(k=>`<a href="${esc(safe(data.settings[k]))}" target="_blank" rel="noopener noreferrer">${k[0].toUpperCase()+k.slice(1)} ↗</a>`).join('')}</div>`;$('.contact-heading').append(contacts);
 document.title=data.seo.title;const meta=(key,val,property=false)=>{let el=document.head.querySelector(`meta[${property?'property':'name'}="${key}"]`);if(!el){el=document.createElement('meta');el.setAttribute(property?'property':'name',key);document.head.append(el)}el.content=val};meta('description',data.seo.description);meta('keywords',data.seo.keywords);meta('og:title',data.seo.ogTitle||data.seo.title,true);meta('og:description',data.seo.ogDescription||data.seo.description,true);if(safe(data.seo.ogImage,true))meta('og:image',new URL(data.seo.ogImage,location.origin).href,true);if(safe(data.settings.favicon,true))$('link[rel=icon]').href=data.settings.favicon;
}
window.cloudNestEnquiryConnected=connected;
// Attach the existing navigation, dialogs and motion only after CMS rendering.
for(const src of ['motion.js','app.js'])await new Promise(resolve=>{const script=document.createElement('script');script.src='/'+src;script.onload=resolve;script.onerror=resolve;document.body.append(script)});
if(data){
 document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>{const r=data.projects.find(v=>v.id===b.dataset.project);const d=$('#article-dialog');$('#article-title').textContent=r.title;$('#article-body').innerHTML=`<p>${esc(r.client)} · ${esc(r.category)}</p><p>${esc(r.description)}</p><p>${esc(r.technologies)}</p>${image(r.image,r.title,'cms-project-image')}${lines(r.gallery).map(u=>image(u,r.title,'cms-project-image')).join('')}${safe(r.url)?`<p><a class="button outline" href="${esc(safe(r.url))}" target="_blank" rel="noopener noreferrer">Visit project ↗</a></p>`:''}`;d.showModal();document.body.style.overflow='hidden';d.addEventListener('close',()=>b.focus(),{once:true});}));
}
if(connected){
 const clean=$('#project-form');
 $('.submit-button').innerHTML='Send your enquiry <span>↗</span>';$('.form-note').textContent='Your details are sent securely to Cloud Nest and stored so we can respond to your enquiry.';$('.contact-form-wrap h3').textContent='Tell us about your project';
 const trap=document.createElement('input');trap.name='website';trap.tabIndex=-1;trap.autocomplete='off';trap.setAttribute('aria-hidden','true');trap.className='cms-honeypot';clean.append(trap);
 clean.addEventListener('submit',async e=>{e.preventDefault();if(!clean.reportValidity())return;const submit=clean.querySelector('[type=submit]'),status=$('#form-status');submit.disabled=true;submit.textContent='Sending…';status.textContent='';const fd=new FormData(clean);
 try{const response=await fetch(window.CLOUD_NEST_API_ORIGIN+'/api/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:fd.get('name'),email:fd.get('email'),company:fd.get('company'),subject:fd.get('service')+' · '+fd.get('plan'),message:fd.get('message'),website:fd.get('website')}),signal:AbortSignal.timeout(15000)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Your enquiry could not be sent.');status.textContent='Thank you. Your enquiry has been received.';clean.reset()}catch(err){status.textContent=err.message||'Unable to send your enquiry. Please try again.'}finally{submit.disabled=false;submit.innerHTML='Send your enquiry <span>↗</span>'}});
}
})();
